/**
 * Fonts for text the bundled Inter does not draw, and the order the page tries them in.
 * Everything here is plain data and string tests, so the Node side (holds, the sweep,
 * the font generator) and the page share it. The faces themselves are declared in
 * fallback-fonts.css (generated by scripts/gen-fallback-fonts.ts) and loaded by
 * fonts.ts before anything is measured.
 */

export interface FallbackFont {
  /** Family name the page knows the face by. */
  family: string;
  /** What it is there for, for the report. */
  script: string;
  /** npm package and stylesheet the faces come from. */
  pkg: string;
  css: string;
  /** Which of the package's subsets to keep. */
  subsets: (name: string) => boolean;
}

const numbered = (name: string) => /^\d+$/.test(name);

/**
 * In the order they are tried after Inter: colour emoji first (CJK fonts carry a few
 * text symbols an emoji should not take), then the scripts with their own letters,
 * then Chinese, Japanese and Korean (reordered per graphic, see `cjkOrder`).
 */
export const FALLBACK_FONTS: readonly FallbackFont[] = [
  { family: 'Kilo Emoji', script: 'emoji', pkg: '@fontsource/noto-color-emoji', css: '400.css', subsets: numbered },
  { family: 'Kilo Arabic', script: 'Arabic', pkg: '@fontsource-variable/noto-sans-arabic', css: 'wght.css', subsets: (n) => n === 'arabic' },
  { family: 'Kilo Hebrew', script: 'Hebrew', pkg: '@fontsource-variable/noto-sans-hebrew', css: 'wght.css', subsets: (n) => n === 'hebrew' },
  { family: 'Kilo Devanagari', script: 'Devanagari', pkg: '@fontsource-variable/noto-sans-devanagari', css: 'wght.css', subsets: (n) => n === 'devanagari' },
  { family: 'Kilo Thai', script: 'Thai', pkg: '@fontsource-variable/noto-sans-thai', css: 'wght.css', subsets: (n) => n === 'thai' },
  { family: 'Kilo JP', script: 'Japanese', pkg: '@fontsource-variable/noto-sans-jp', css: 'wght.css', subsets: numbered },
  { family: 'Kilo SC', script: 'Chinese (simplified)', pkg: '@fontsource-variable/noto-sans-sc', css: 'wght.css', subsets: numbered },
  { family: 'Kilo KR', script: 'Korean', pkg: '@fontsource-variable/noto-sans-kr', css: 'wght.css', subsets: numbered },
];

const KANA = /[\p{Script=Hiragana}\p{Script=Katakana}]/u;
const HANGUL = /\p{Script=Hangul}/u;

/**
 * Han characters look different in Japanese and Chinese. The graphic's own text picks
 * which CJK face goes first: Japanese when it has kana, Korean when it has Hangul,
 * Chinese otherwise.
 */
export function cjkOrder(text: string): string[] {
  if (KANA.test(text)) return ['Kilo JP', 'Kilo SC', 'Kilo KR'];
  if (HANGUL.test(text)) return ['Kilo KR', 'Kilo JP', 'Kilo SC'];
  return ['Kilo SC', 'Kilo JP', 'Kilo KR'];
}

let hint = '';
/** Sets the text of the graphic being drawn, which orders the CJK faces. */
export function setTextHint(text: string): void {
  hint = text;
}

/** The fallback families after Inter, in the order the page tries them for the current graphic. */
export function fallbackFamilies(): string[] {
  const cjk = cjkOrder(hint);
  return [...FALLBACK_FONTS.map((f) => f.family).filter((f) => !cjk.includes(f)), ...cjk];
}

const RTL = /[֐-ࣿיִ-﷿ﹰ-﻿\u{10800}-\u{10FFF}\u{1E800}-\u{1EFFF}]/u;
const STRONG = /[\p{L}]/u;

/** The direction of a run of text: that of its first letter (the bidi "first strong" rule). */
export function textDirection(text: string): 'rtl' | 'ltr' {
  for (const ch of text) {
    if (RTL.test(ch) && STRONG.test(ch)) return 'rtl';
    if (STRONG.test(ch)) return 'ltr';
  }
  return 'ltr';
}

/** Every string in a graphic's props, for the font hint and the faces to load. */
export function textOf(props: unknown): string {
  if (typeof props === 'string') return props;
  if (Array.isArray(props)) return props.map(textOf).join(' ');
  if (props && typeof props === 'object') return Object.values(props as Record<string, unknown>).map(textOf).join(' ');
  return '';
}
